<section class="admin-welcome"><div><p class="eyebrow">MODIFICATION</p><h1><?= htmlspecialchars($course['title']) ?></h1><p>Modifiez les informations commerciales et les prérequis sans perdre le programme.</p></div><div><a class="btn secondary" href="/admin/cours/programme?course=<?= $course['id'] ?>">Programme</a> <a class="btn secondary" href="/admin/cours">← Retour</a></div></section><form class="panel admin-editor" method="post" action="/admin/cours/modifier"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><div class="editor-section"><h3>Informations générales</h3><div class="field-grid"><label class="full">Titre *<input name="title" maxlength="190" value="<?= htmlspecialchars($course['title']) ?>" required></label><label class="full">Description<textarea name="description" rows="5"><?= htmlspecialchars($course['description']??'') ?></textarea></label><label>Filière<input name="sector" value="<?= htmlspecialchars($course['category']) ?>"></label><label>Mode<select name="mode"><?php foreach(['Présentiel','En ligne','Mixte'] as $mode): ?><option <?= $course['mode']===$mode?'selected':'' ?>><?= $mode ?></option><?php endforeach ?></select></label><label>Durée<input name="duration" value="<?= htmlspecialchars($course['duration_label']) ?>"></label><label>Prix FCFA<input type="number" name="price" min="0" value="<?= (int)$course['price'] ?>"></label><label>Statut<select name="status"><option value="draft" <?= $course['status']==='draft'?'selected':'' ?>>Brouillon</option><option value="published" <?= $course['status']==='published'?'selected':'' ?>>Publiée</option><option value="archived" <?= $course['status']==='archived'?'selected':'' ?>>Archivée</option></select></label></div></div><div class="editor-section prerequisite-editor"><h3>Prérequis</h3><p>Ajoutez, corrigez ou supprimez les prérequis oubliés lors de la création.</p><div class="prerequisite-columns"><div><h4>Compétences nécessaires</h4><div data-skill-list><?php foreach($skills?:[''] as $skill): ?><div class="repeat-field"><input name="prerequisite_skills[]" value="<?= htmlspecialchars($skill) ?>" placeholder="Ex. Connaître les règles HSE"><button type="button" data-remove-field>×</button></div><?php endforeach ?></div><button type="button" class="btn secondary" data-add-skill>+ Ajouter une compétence</button></div><div><h4>Formations préalables</h4><div data-course-list><?php foreach($requiredCourses?:[''] as $required): ?><div class="repeat-field"><select name="prerequisite_courses[]"><option value="">Aucune</option><?php foreach($availableCourses as $available): ?><option value="<?= $available['id'] ?>" <?= (string)$required===(string)$available['id']?'selected':'' ?>><?= htmlspecialchars($available['title']) ?></option><?php endforeach ?></select><button type="button" data-remove-field>×</button></div><?php endforeach ?></div><button type="button" class="btn secondary" data-add-course>+ Ajouter une formation</button></div></div></div><footer><a class="btn secondary" href="/admin/cours">Annuler</a><button class="btn primary">Enregistrer les modifications</button></footer></form><style>.admin-editor textarea{border:1px solid var(--line);border-radius:7px;padding:12px}.prerequisite-editor>p{color:var(--muted)}.prerequisite-columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.repeat-field{display:flex;gap:7px;margin:8px 0}.repeat-field input,.repeat-field select{height:42px;flex:1;border:1px solid var(--line);border-radius:7px;padding:0 10px}.repeat-field button{width:40px;border:1px solid var(--line);background:#fff;color:#a74739;border-radius:7px}@media(max-width:700px){.prerequisite-columns{grid-template-columns:1fr}}</style>
